mapper.update:
UPDATE local_user_credential
SET failed_attempts = #{failedAttempts},
    locked_until = #{lockedUntil}
WHERE user_id = #{userId}

UPDATE auth_session
SET token_hash = #{newTokenHash},
    last_seen_at = #{now}
WHERE id = #{sessionId}
  AND token_hash = #{currentTokenHash}
  AND expires_at > #{now}
  AND revoked_at IS NULL

UPDATE auth_session
SET revoked_at = #{now}
WHERE id = #{sessionId}
  AND revoked_at IS NULL
